 if(!panel){panel=document.createElement('section');panel.id='studio-home-creation';panel.className='studio-form-card';panel.setAttribute('aria-label','最近的歌曲创作');panel.innerHTML='<strong data-home-creation-title></strong><p data-home-creation-status role="status" aria-live="polite"></p><button type="button" class="rs-outline">查看创作与试听</button>';q('.rs-hero').after(panel);panel.style.cssText='max-width:900px;margin:24px auto;padding:20px;';panel.querySelector('button').onclick=()=>{const d=drafts.find(d=>d.id===panel.dataset.draftId);showCreate();if(d&&d.stage!=='confirmed'){lyricDraftId=d.id;showDraftReview(d);}else{activeBatchId=d?.batch_id||creations[0]?.batch_id;$('studio-create-status').textContent=d?draftProgress(d):creationProgress(creations[0]);}};}
 panel.dataset.draftId=latest.draft?.id||'';panel.querySelector('button').textContent=latest.draft&&latest.draft.stage!=='confirmed'?'查看并确认歌词':'查看创作与试听';panel.querySelector('[data-home-creation-title]').textContent=displaySongTitle(latest.batch?.title||latest.input?.title||'最近的创作');
 panel.querySelector('[data-home-creation-status]').textContent=latest.draft?draftProgress(latest.draft):creationProgress(latest);
