 const blocked=generationIsBlocked({creating,lyricsRequest,recovering});
 const b=$('studio-generate-song');if(b)b.textContent=mode==='simple'?'生成歌词':'核对歌词';if(b)b.disabled=blocked||(mode==='simple'?$('studio-simple-prompt').value.trim().length<3:!$('studio-custom-lyrics').value.trim());
