 try{const flow=creations.find(c=>c.id===id);if(flow){acceptCreationFlow(await api('/api/creation/jobs/'+id+'/resume',{}));}else await api('/api/generation/batches/'+id+'/resume',{});await refresh();}
 finally{resumingBatches.delete(id);renderBatches();}
