  if(creationRecovery.state.pending){
   const previous=await creationRecovery.inspect();
   const resolved=previous.kind==='missing'?await creationRecovery.cancel():previous;
   if(resolved.kind==='accepted'){await refresh();return;}
   if(resolved.kind!=='cancelled'&&resolved.kind!=='none')throw Error('上一次创作结果尚未确认，请稍后重试。');
  }
